-- Уникальность hash/pair и наличие обоих родителей.
SELECT count(*) AS n FROM (SELECT link_hk AS k FROM {{target:oil_dds__link_well_field}} GROUP BY link_hk HAVING link_hk IS NULL OR count(*)>1 UNION ALL SELECT min(link_hk) AS k FROM {{target:oil_dds__link_well_field}} GROUP BY well_hk,field_hk HAVING count(*)>1 UNION ALL SELECT l.link_hk AS k FROM {{target:oil_dds__link_well_field}} l LEFT JOIN {{target:oil_dds__hub_well}} w ON w.well_hk=l.well_hk LEFT JOIN {{target:oil_dds__hub_field}} f ON f.field_hk=l.field_hk WHERE w.well_hk IS NULL OR f.field_hk IS NULL) q;
